package com.foody.communications.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="business_messages") public class BusinessMessage {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="target_business_id") private Long targetBusinessId; @Column(name="audience_business_id_cutoff") private Long audienceBusinessIdCutoff; @Column(name="sender_admin_user_id",nullable=false) private Long senderAdminUserId; @Enumerated(EnumType.STRING) @Column(name="message_type",nullable=false) private BusinessMessageType messageType; @Column(nullable=false,length=160) private String subject; @Column(nullable=false,length=4000) private String body; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @PrePersist void create(){createdAt=Instant.now();}
 public Long getId(){return id;} public Long getTargetBusinessId(){return targetBusinessId;} public void setTargetBusinessId(Long v){targetBusinessId=v;} public Long getAudienceBusinessIdCutoff(){return audienceBusinessIdCutoff;} public void setAudienceBusinessIdCutoff(Long v){audienceBusinessIdCutoff=v;} public Long getSenderAdminUserId(){return senderAdminUserId;} public void setSenderAdminUserId(Long v){senderAdminUserId=v;} public BusinessMessageType getMessageType(){return messageType;} public void setMessageType(BusinessMessageType v){messageType=v;} public String getSubject(){return subject;} public void setSubject(String v){subject=v;} public String getBody(){return body;} public void setBody(String v){body=v;} public Instant getCreatedAt(){return createdAt;}
}
